package com.example.rifd.DTOIn;

import com.example.rifd.Enum.StaffLevel;
import com.example.rifd.Enum.StaffRole;
import com.example.rifd.Enum.StaffSpecialty;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.time.LocalTime;

// username + password are generated by the server (shown once in the response)
public record StaffCreateDTOIn(
        @NotBlank(message = "name is required")
        @Size(max = 100, message = "name is too long")
        String name,

        @Size(max = 20, message = "phone is too long")
        String phone,

        @Email(message = "email is invalid")
        @Size(max = 120, message = "email is too long")
        String email,

        @NotNull(message = "role is required")
        StaffRole role,

        // required for FIELD only
        StaffSpecialty specialty,
        StaffLevel level,

        @NotBlank(message = "homeZoneCode is required")
        @Size(max = 20, message = "homeZoneCode is too long")
        String homeZoneCode,

        // optional: whole day if empty (night shifts like 22:00 -> 06:00 are supported)
        LocalTime shiftStart,
        LocalTime shiftEnd
) {
}